INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (320, 'Ei-Kraft: TechnschrWdrstnd+', 'Egg Power: Tech Resilience+', NULL, NULL, 'Ei-Kraft: TechnschrWdrstnd+', 'Egg Power: Tech Resilience+', 'Verringert erlittenen Technik-Typ-Schaden.', 'Reduces Technical Type damage taken.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (321, 'Ei-Kraft: Unversehrt', 'Egg Power: Unscathed', NULL, NULL, 'Ei-Kraft: Unversehrt', 'Egg Power: Unscathed', 'Hebt erlittenen Schaden nach einer gewonnenen Konfrontation auf und erhöht den Schaden, der Gegnern zugefügt wird.', 'Negates damage after winning a Head-to-Head and increases damage dealt to enemies.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (322, 'Ei-Kraft: Unversehrt+', 'Egg Power: Unscathed+', NULL, NULL, 'Ei-Kraft: Unversehrt+', 'Egg Power: Unscathed+', 'Hebt erlittenen Schaden nach einer gewonnenen Konfrontation auf und erhöht den Schaden, der Gegnern zugefügt wird, bedeutend.', 'Negates damage after winning a Head-to-Head and greatly increases damage dealt to enemies.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (323, 'Ei-Kraft: Gesteigerte Moral', 'Egg Power: High Morale', NULL, NULL, 'Ei-Kraft: Gesteigerte Moral', 'Egg Power: High Morale', 'Verlängert die Dauer von verwendeten Stärkungen etwas, wenn sie durch eigene Fähigkeiten angewendet werden.', 'Slightly extends the duration of buffs when applied by own skills.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (324, 'Ei-Kraft: GesteigerteMoral+', 'Egg Power: High Morale+', NULL, NULL, 'Ei-Kraft: GesteigerteMoral+', 'Egg Power: High Morale+', 'Verlängert die Dauer von verwendeten Stärkungen, wenn sie durch eigene Fähigkeiten angewendet werden.', 'Extends the duration of buffs when applied by own skills.');
