INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (327, 'Feurige Seele', 'Fiery Spirit', NULL, 'fire', 'Feurige Seele', 'Fiery Spirit', 'Erhöht vorübergehend den verursachten Feuerschaden, wenn ein Monster während des Kampfes transformiert.', 'Temporarily increases fire damage dealt when a monster undergoes a transformation during battle.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (329, 'Erwachte Flamme', 'Awakened Flame', NULL, 'fire', 'Erwachte Flamme', 'Awakened Flame', 'Erhöht vorübergehend den verursachten Feuerschaden, wenn ein anormaler Status zugefügt wurde.', 'Temporarily increases fire damage dealt when inflicted with abnormal status.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (331, 'Heimlichkeit', 'Stealthy', NULL, NULL, 'Heimlichkeit', 'Stealthy', 'Erhöht die Kritische Rate, wenn man nicht im Visier einer Kampflinie ist.', 'Increases Crit Rate when not targeted by any Battle Lines.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (333, 'Eiskalt', 'Ice-Cold', NULL, 'ice', 'Eiskalt', 'Ice-Cold', 'Erhöht vorübergehend Kritische Rate und verursachten Eisschaden, nachdem ein kritischer Treffer erlitten wurde.', 'Temporarily increases Crit Rate and ice damage dealt after taking a critical hit.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (335, 'Rückenwind', 'Tailwind', NULL, NULL, 'Rückenwind', 'Tailwind', 'Erhöht die Geschwindigkeit bei 50 % TP oder weniger.', 'Increases Speed at 50% HP or less.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (337, 'Tausend Schnitte', 'Thousand Cuts', NULL, NULL, 'Tausend Schnitte', 'Thousand Cuts', 'Angriffe können Blutung zufügen.', 'Attacks have a chance to inflict Bleeding.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (339, 'Schützender Panzer', 'Protective Shell', NULL, NULL, 'Schützender Panzer', 'Protective Shell', 'Verringert vorübergehend den durch Gegner erlittenen Schaden, wenn ein anormaler Status zugefügt wurde.', 'Temporarily reduces damage taken from enemies when inflicted with abnormal status.');
INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (341, 'Garangolm-Ansturm', 'Garangolm Charge', NULL, NULL, 'Garangolm-Ansturm', 'Garangolm Charge', 'Erhöht verursachten Schaden des Wyvernseelen-Balkens.', 'Increases damage dealt to the Wyvernsoul Gauge.');
