INSERT INTO genes (game_id, name_de, name_en, gene_type, element, skill_name_de, skill_name_en, description_de, description_en) VALUES (358, 'Beweis eines Helden +1', 'Heroic Testament (S)', NULL, 'dragon', 'Beweis eines Helden +1', 'Heroic Testament (S)', 'Die Macht von Helden, die einen Unheilvollen Drachenältesten erlegt haben. Erhöht die maximalen TP sowie den zugefügten Schaden etwas und verringert den erlittenen Schaden etwas.', 'Power held by heroes who slayed a Calamitous Elder Dragon. Slightly increases maximum HP and damage dealt to enemies, and slightly reduces damage taken.');
